                    </div>
                  </div>

                  <div className="space-y-2">
                    <label htmlFor="message" className="text-sm font-medium">Project Details <span className="text-red-500">*</span></label>
                    <textarea 
                      id="message"
                      name="message"
                      required
                      value={formData.message}
                      onChange={handleChange}
                      rows={5}
                      className="w-full px-4 py-3 rounded-xl bg-background border border-border focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all resize-none"
                      placeholder="Tell us about your project requirements, timeline, and goals..."
                    />
                  </div>

                  <button 
                    type="submit" 
                    disabled={status === "loading"}
                    className="w-full py-4 bg-primary text-white rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-primary/90 transition-colors disabled:opacity-70"
                  >
                    {status === "loading" ? (
                      <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : status === "success" ? (
                      <>Message Sent <CheckCircle2 className="w-5 h-5" /></>
                    ) : status === "error" ? (
                      <>Error Sending <AlertCircle className="w-5 h-5" /></>
                    ) : (
                      <>Submit Inquiry <Send className="w-5 h-5" /></>
                    )}
                  </button>

                  {status === "success" && (
                     <p className="text-green-500 text-sm font-medium text-center bg-green-500/10 py-2 rounded-lg">
                       Thank you! Your message has been sent successfully. We will get back to you shortly.
                     </p>
                  )}
                  {status === "error" && (
                     <p className="text-red-500 text-sm font-medium text-center bg-red-500/10 py-2 rounded-lg">
                       There was an error sending your message. Please try again later.
                     </p>
                  )}
                </form>
              </div>
            </motion.div>

          </div>
        </div>
      </section>
    </div>
  );
}

