"use client";

import { useEffect, useRef, useState } from "react";
import { useInView } from "framer-motion";

function Counter({ end, duration = 2, suffix = "" }: { end: number, duration?: number, suffix?: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  useEffect(() => {
    if (isInView) {
      let start = 0;
      const endVal = end;
      if (start === endVal) return;

      const totalMilSecDur = duration * 1000;
      const incrementTime = (totalMilSecDur / endVal) * 2;

      const timer = setInterval(() => {
        start += 1;
        setCount(start);
        if (start >= endVal) clearInterval(timer);
      }, incrementTime);

      return () => clearInterval(timer);
    }
  }, [end, duration, isInView]);

  return (
    <span ref={ref} className="text-4xl md:text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-primary to-accent">
      {count}{suffix}
    </span>
  );
}

export function StatsSection() {
  const stats = [
    { label: "Projects Delivered", value: 50, suffix: "+" },
    { label: "Happy Clients", value: 30, suffix: "+" },
    { label: "Industries Served", value: 10, suffix: "+" },
    { label: "Years Experience", value: 5, suffix: "+" },
  ];

  return (
    <section className="py-20 bg-background border-y border-border">
      <div className="container mx-auto px-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-8 md:gap-4 text-center">
          {stats.map((stat, i) => (
            <div key={i} className="flex flex-col items-center justify-center p-6 border-r last:border-r-0 border-border/50 max-md:[&:nth-child(even)]:border-r-0">
              <Counter end={stat.value} suffix={stat.suffix} />
              <p className="mt-4 text-sm md:text-base font-semibold text-foreground/80 uppercase tracking-wider">
                {stat.label}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

